PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?term ?mesh WHERE {
  {
    ?item wdt:P486 ?mesh ;
          rdfs:label ?label .
    FILTER(LANG(?label) = "zh")
    BIND(STR(?label) AS ?term)
  }
  UNION
  {
    ?item wdt:P486 ?mesh ;
          skos:altLabel ?alt .
    FILTER(LANG(?alt) = "zh")
    BIND(STR(?alt) AS ?term)
  }
  __MESH_PREFIX_FILTER__
}
